+  rv = sConnection->ExecuteSimpleSQL(
+      "CREATE TABLE messages ( \
+        id INTEGER PRIMARY KEY, \
+        folderId INTEGER REFERENCES folders(id), \
+        threadId INTEGER REFERENCES messages(id), \
+        threadParent INTEGER REFERENCES messages(id), \
+        messageId TEXT, \
+        date INTEGER, \
+        sender TEXT, \
